//! The generated compose file (.state/compose.yml): compose.yml.j2 rendered with sandbox.toml and the host
//! settings into the one file docker compose runs with.

use crate::support::*;
use sha2::{Digest, Sha256};
use std::fs;
use yaml_rust2::{Yaml, YamlLoader};

fn header(f: &Fixture) -> String {
    format!(
        "# Generated by sandbox {} — changes are overwritten. Settings: sandbox.toml.\n# Rendered from compose.yml.j2 with sandbox.toml and this machine's settings.\n# Relative paths are relative to the .sandbox folder.",
        f.app_version()
    )
}

/// Run a cheap docker command so the file is (re)generated, and return its text.
fn generate(f: &Fixture) -> String {
    // No containers yet: some tests change the id, which must not count as another project's container group.
    let r = f.run_with(
        &["status"],
        RunOpts::default().rules(vec![rule("ps -a --filter").stdout("")]),
    );
    assert_exit(&r, 0);
    assert!(f.generated_file().exists(), "No generated file.\n{r}");
    fs::read_to_string(f.generated_file()).unwrap()
}

fn generate_parsed(f: &Fixture) -> Yaml {
    parse(&generate(f))
}

fn parse(text: &str) -> Yaml {
    let mut docs = YamlLoader::load_from_str(text).expect("valid YAML");
    assert_eq!(docs.len(), 1);
    let root = docs.remove(0);
    assert!(matches!(root, Yaml::Hash(_)), "{root:?}");
    root
}

fn lookup<'a>(n: &'a Yaml, key: &str) -> Option<&'a Yaml> {
    match n {
        Yaml::Hash(h) => h.get(&Yaml::String(key.to_string())),
        _ => None,
    }
}

fn at<'a>(n: &'a Yaml, path: &[&str]) -> &'a Yaml {
    let mut n = n;
    for k in path {
        n = lookup(n, k).unwrap_or_else(|| panic!("missing key '{k}'"));
    }
    n
}

fn has(n: &Yaml, path: &[&str]) -> bool {
    let mut n = n;
    for k in path {
        match lookup(n, k) {
            Some(x) => n = x,
            None => return false,
        }
    }
    true
}

/// The text of a scalar, whatever its YAML type (the way YamlDotNet's `Value` shows it).
fn scalar(n: &Yaml) -> String {
    match n {
        Yaml::String(s) | Yaml::Real(s) => s.clone(),
        Yaml::Integer(i) => i.to_string(),
        Yaml::Boolean(b) => b.to_string(),
        Yaml::Null => String::new(),
        other => panic!("not a scalar: {other:?}"),
    }
}

fn str_(n: &Yaml, path: &[&str]) -> String {
    scalar(at(n, path))
}

fn seq(n: &Yaml, path: &[&str]) -> Vec<String> {
    match at(n, path) {
        Yaml::Array(a) => a.iter().map(scalar).collect(),
        other => panic!("not a sequence: {other:?}"),
    }
}

fn keys(n: &Yaml) -> Vec<String> {
    match n {
        Yaml::Hash(h) => h.keys().map(scalar).collect(),
        other => panic!("not a mapping: {other:?}"),
    }
}

#[derive(Debug, PartialEq, Eq)]
struct Bind {
    source: String,
    target: String,
    read_only: bool,
}

fn bind(source: impl Into<String>, target: impl Into<String>, read_only: bool) -> Bind {
    Bind {
        source: source.into(),
        target: target.into(),
        read_only,
    }
}

/// The bind mounts of the desktop (the generated project mounts; home skipped).
fn binds(root: &Yaml) -> Vec<Bind> {
    let Yaml::Array(volumes) = at(root, &["services", "desktop", "volumes"]) else {
        panic!("volumes")
    };
    volumes
        .iter()
        .filter(|v| matches!(v, Yaml::Hash(_)))
        .filter(|m| str_(m, &["type"]) == "bind")
        .map(|m| {
            assert_eq!(keys(m), ["type", "source", "target", "read_only"]);
            let ro = str_(m, &["read_only"]);
            assert!(ro == "true" || ro == "false", "{ro}");
            Bind {
                source: str_(m, &["source"]),
                target: str_(m, &["target"]),
                read_only: ro == "true",
            }
        })
        .collect()
}

/// A service with its YAML merge key (`<<: *hardened`) applied, as docker compose reads it.
fn service(root: &Yaml, name: &str) -> Yaml {
    let svc = at(root, &["services", name]);
    let Yaml::Hash(h) = svc else {
        panic!("service {name}")
    };
    let mut merged = yaml_rust2::yaml::Hash::new();
    for (k, v) in h {
        if scalar(k) != "<<" {
            merged.insert(k.clone(), v.clone());
        }
    }
    if let Some(Yaml::Hash(m)) = lookup(svc, "<<") {
        for (k, v) in m {
            if !merged.contains_key(k) {
                merged.insert(k.clone(), v.clone());
            }
        }
    }
    Yaml::Hash(merged)
}

fn project(f: &Fixture, ro: bool) -> Bind {
    bind(f.project_dir.as_str(), f.work_dir(), ro)
}
fn sandbox_dir(f: &Fixture) -> Bind {
    bind(f.dir.as_str(), format!("{}/.sandbox", f.work_dir()), true)
}
fn git_dir(f: &Fixture) -> Bind {
    bind(
        f.project_dir.join(".git").as_str(),
        format!("{}/.git", f.work_dir()),
        true,
    )
}

fn expected_ids() -> (u32, u32) {
    #[cfg(unix)]
    {
        let (u, g) = (
            rustix::process::getuid().as_raw(),
            rustix::process::getgid().as_raw(),
        );
        if u != 0 {
            return (u, g);
        }
    }
    (1000, 1000)
}

fn q(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

/// The default sandbox.toml with extra lines appended to one of its sections.
fn append(f: &Fixture, section: &str, lines: &str) {
    let mut conf = f.read_conf();
    let marker = format!("[{section}]\n");
    match conf.find(&marker) {
        None => conf.push_str(&format!("\n[{section}]\n{lines}")),
        Some(at) => conf.insert_str(at + marker.len(), lines),
    }
    f.write_conf(&conf);
}

fn env(f: &Fixture, key: &str) -> String {
    str_(
        &service(&generate_parsed(f), "desktop"),
        &["environment", key],
    )
}

// --- the default file -------------------------------------------------------

#[test]
fn default_file_matches_exactly() {
    let f = Fixture::new();
    let (uid, gid) = expected_ids();
    let vol = |b: Bind| {
        format!(
            "      - {{type: bind, source: {}, target: {}, read_only: {}}}",
            q(&b.source),
            q(&b.target),
            if b.read_only { "true" } else { "false" }
        )
    };
    let work_dir = f.work_dir();
    let expected = [
        header(&f),
        "networks:".into(),
        "  sandbox:            # desktop <-> proxy/gateway; NO internet route".into(),
        "    internal: true".into(),
        "  egress: {}          # proxy -> internet".into(),
        "  ui: {}              # gateway -> published localhost port".into(),
        "".into(),
        "x-hardened: &hardened".into(),
        "  read_only: true".into(),
        "  cap_drop: [ALL]".into(),
        "  security_opt: [\"no-new-privileges:true\"]".into(),
        "  restart: unless-stopped".into(),
        "  volumes:".into(),
        "    - .:/sandbox:ro   # allowlist.txt (live: \"sandbox reload\")".into(),
        "".into(),
        "services:".into(),
        "  proxy:".into(),
        "    <<: *hardened".into(),
        "    build: ./.state/proxy".into(),
        "    command: [\"tinyproxy\", \"-d\", \"-c\", \"/etc/tinyproxy/tinyproxy.conf\"]".into(),
        "    networks: [sandbox, egress]".into(),
        "    extra_hosts:".into(),
        "      - \"host.docker.internal:host-gateway\"   # only reachable if allowlisted".into(),
        "    healthcheck:".into(),
        "      test: [\"CMD\", \"nc\", \"-z\", \"127.0.0.1\", \"3128\"]".into(),
        "      interval: 10s".into(),
        "      timeout: 3s".into(),
        "      retries: 3".into(),
        "".into(),
        "  gateway:".into(),
        "    <<: *hardened".into(),
        "    build: ./.state/proxy".into(),
        "    command: [\"socat\", \"TCP-LISTEN:3001,fork,reuseaddr\", \"TCP:desktop:3001\"]".into(),
        "    networks: [sandbox, ui]".into(),
        "    ports:".into(),
        "      - \"127.0.0.1::3001\"".into(),
        "    depends_on: [proxy]".into(),
        "".into(),
        "  desktop:".into(),
        "    build:".into(),
        "      context: ./.state/desktop".into(),
        "      args:".into(),
        "        INSTALL_CLAUDE: \"true\"".into(),
        "        INSTALL_CLAUDE_CODE: \"false\"".into(),
        "        INSTALL_DOTNET: \"10.0\"".into(),
        "        INSTALL_NODE: \"false\"".into(),
        "    hostname: sandbox".into(),
        "    shm_size: 1gb".into(),
        "    labels:".into(),
        format!("      sandbox.id: \"{ID}\""),
        "    environment:".into(),
        "      TITLE: \"AI Sandbox\"".into(),
        "      SANDBOX_SUDO: \"true\"".into(),
        "      HTTP_PROXY: http://proxy:3128".into(),
        "      HTTPS_PROXY: http://proxy:3128".into(),
        "      http_proxy: http://proxy:3128".into(),
        "      https_proxy: http://proxy:3128".into(),
        "      NO_PROXY: localhost,127.0.0.1,::1".into(),
        "      no_proxy: localhost,127.0.0.1,::1".into(),
        format!("      PUID: \"{uid}\""),
        format!("      PGID: \"{gid}\""),
        "      TZ: \"Europe/Vienna\"".into(),
        format!("      SANDBOX_WORKDIR: \"{work_dir}\""),
        "    volumes:".into(),
        "      - home:/config            # persistent home: logins, IDE settings, Toolbox IDEs".into(),
        vol(project(&f, false)),
        vol(sandbox_dir(&f)),
        vol(git_dir(&f)),
        "    networks: [sandbox]".into(),
        "    mem_limit: \"8g\"".into(),
        "    pids_limit: 4096".into(),
        "    depends_on: [proxy]".into(),
        "    restart: unless-stopped".into(),
        "    healthcheck:".into(),
        "      # Ready = web UI answers AND the KDE shell is running (avoids the".into(),
        "      # \"first page load fails\" race when the browser opens too early).".into(),
        "      test: [\"CMD-SHELL\", \"curl -skf -o /dev/null https://localhost:3001/ && pgrep -f plasmashell >/dev/null\"]".into(),
        "      interval: 5s".into(),
        "      timeout: 5s".into(),
        "      retries: 3".into(),
        "      start_period: 180s".into(),
        "".into(),
        "volumes:".into(),
        "  home:".into(),
        "".into(),
    ]
    .join("\n");
    let text = generate(&f);
    assert_eq!(expected, text);
    assert!(!text.contains('\r'));
    assert!(!text.contains("\n..."));
    assert!(
        !fs::read(f.generated_file())
            .unwrap()
            .starts_with(&[0xEF, 0xBB, 0xBF]),
        "BOM"
    );
}

#[test]
fn default_file_parses() {
    let f = Fixture::new();
    let root = generate_parsed(&f);
    assert_eq!(
        keys(&root),
        ["networks", "x-hardened", "services", "volumes"]
    );
    assert_eq!(
        keys(at(&root, &["services"])),
        ["proxy", "gateway", "desktop"]
    );
    assert_eq!(
        seq(&root, &["services", "gateway", "ports"]),
        ["127.0.0.1::3001"]
    );
    assert_eq!(
        str_(&root, &["services", "desktop", "labels", "sandbox.id"]),
        ID
    );
    assert_eq!(env(&f, "SANDBOX_WORKDIR"), f.work_dir());
    assert_eq!(env(&f, "TZ"), "Europe/Vienna");
    assert_eq!(
        binds(&root),
        [project(&f, false), sandbox_dir(&f), git_dir(&f)]
    );
}

/// The x-hardened settings apply to proxy and gateway (through the merge key), not to the desktop.
#[test]
fn proxy_and_gateway_are_hardened() {
    let f = Fixture::new();
    let root = generate_parsed(&f);
    for s in ["proxy", "gateway"] {
        let svc = service(&root, s);
        assert_eq!(str_(&svc, &["read_only"]), "true");
        assert_eq!(seq(&svc, &["cap_drop"]), ["ALL"]);
        assert_eq!(seq(&svc, &["security_opt"]), ["no-new-privileges:true"]);
        assert_eq!(seq(&svc, &["volumes"]), [".:/sandbox:ro"]);
    }
    assert!(!has(&service(&root, "desktop"), &["read_only"]));
    assert!(
        seq(&root, &["services", "gateway", "command"])
            .contains(&"TCP-LISTEN:3001,fork,reuseaddr".to_string())
    );
}

#[test]
fn shipped_sandbox_toml_renders_all_tools() {
    let f = Fixture::new();
    fs::copy(f.init_templates_dir().join("sandbox.toml"), f.conf_file()).unwrap();
    let root = generate_parsed(&f);
    let args = at(&root, &["services", "desktop", "build", "args"]);
    assert_eq!(
        keys(args),
        [
            "INSTALL_CLAUDE",
            "INSTALL_CLAUDE_CODE",
            "INSTALL_DOTNET",
            "INSTALL_NODE",
            "INSTALL_BUN",
            "INSTALL_RUST",
            "INSTALL_VSCODE",
            "INSTALL_JETBRAINS",
            "INSTALL_APT"
        ]
    );
    assert_eq!(str_(args, &["INSTALL_APT"]), "");
}

#[test]
fn rust_toolchains_become_one_build_arg() {
    let f = Fixture::new();
    f.write_conf("[tools]\nrust = [\"stable\", \"nightly\"]\n");
    let root = generate_parsed(&f);
    let args = at(&root, &["services", "desktop", "build", "args"]);
    assert_eq!(str_(args, &["INSTALL_RUST"]), "stable nightly");
}

