#[test]
fn fixed_ui_port() {
    let f = Fixture::new();
    f.write_conf(&f.read_conf().replace("# ui_port = 3001", "ui_port = 3002"));
    assert_eq!(
        seq(&generate_parsed(&f), &["services", "gateway", "ports"]),
        ["127.0.0.1:3002:3001"]
    );
}

#[test]
fn read_only_workspace_has_no_git_mounts() {
    let f = Fixture::new();
    f.write_conf(
        &f.read_conf()
            .replace("workspace = \"rw\"", "workspace = \"ro\""),
    );
    assert_eq!(binds(&generate_parsed(&f)), [project(&f, true)]);
}

#[test]
fn protect_git_off() {
    let f = Fixture::new();
    f.write_conf(
        &f.read_conf()
            .replace("protect_git = true", "protect_git = false"),
    );
    assert_eq!(
        binds(&generate_parsed(&f)),
        [project(&f, false), sandbox_dir(&f)]
    );
}

#[test]
fn only_existing_git_paths_are_protected() {
    let f = Fixture::new();
    fs::remove_dir(f.project_dir.join(".git").join("hooks")).unwrap();
    assert_eq!(
        binds(&generate_parsed(&f)),
        [project(&f, false), sandbox_dir(&f), git_dir(&f)]
    );

    fs::remove_dir_all(f.project_dir.join(".git")).unwrap();
    assert_eq!(
        binds(&generate_parsed(&f)),
        [project(&f, false), sandbox_dir(&f)]
    );
}

#[test]
fn project_name_does_not_change_the_mount_path() {
    let f = Fixture::new();
    f.write_conf(
        &f.read_conf()
            .replace("# name = \"myproject\"", "name = \"other\""),
    );
    assert_eq!(env(&f, "SANDBOX_WORKDIR"), f.work_dir());
}

#[test]
fn a_new_id_is_derived_from_the_project_path_and_kept() {
    let f = Fixture::new();
    fs::remove_file(f.id_file()).unwrap();
    let digest = Sha256::digest(f.project_dir.as_str().as_bytes());
    let id: String = digest
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect::<String>()[..8]
        .to_string();
    let root = generate_parsed(&f);
    assert_eq!(fs::read_to_string(f.id_file()).unwrap(), format!("{id}\n"));
    assert_eq!(
        str_(&root, &["services", "desktop", "labels", "sandbox.id"]),
        id
    );
    assert_eq!(
        str_(
            &root,
            &["services", "desktop", "environment", "SANDBOX_WORKDIR"]
        ),
        format!("/work/{PROJECT_NAME}-{id}")
    );

    // a stored id is used as-is, even if it doesn't match the path (the project was moved)
    fs::write(f.id_file(), "cafebabe\n").unwrap();
    assert_eq!(
        str_(
            &generate_parsed(&f),
            &["services", "desktop", "labels", "sandbox.id"]
        ),
        "cafebabe"
    );
}

#[test]
fn file_is_regenerated_on_every_docker_command() {
    let f = Fixture::new();
    fs::write(f.generated_file(), "stale").unwrap();
    assert!(generate(&f).starts_with(&format!("{}\n", header(&f))));
    for cmd in ["stop", "reload", "logs"] {
        fs::write(f.generated_file(), "stale").unwrap();
        assert_exit(&f.run(&[cmd]), 0);
        assert!(
            fs::read_to_string(f.generated_file())
                .unwrap()
                .starts_with(&format!("{}\n", header(&f)))
        );
    }
}

#[test]
fn the_old_override_file_is_removed() {
    let f = Fixture::new();
    let old = f.state_dir().join("compose.generated.yml");
    fs::write(&old, "services: {}\n").unwrap();
    generate(&f);
    assert!(!old.exists());
}

// --- [tools] -------------------------------------------------------------------

#[test]
fn tool_values_become_build_args() {
    let f = Fixture::new();
    f.write_conf("[tools]\nclaude = true\nnode = 24\ndotnet = [\"10.0\", \"8.0\"]\njetbrains = \"toolbox rider\"\napt = []\nbun = false\n");
    let root = generate_parsed(&f);
    let args = at(&root, &["services", "desktop", "build", "args"]);
    assert_eq!(
        keys(args),
        [
            "INSTALL_CLAUDE",
            "INSTALL_NODE",
            "INSTALL_DOTNET",
            "INSTALL_JETBRAINS",
            "INSTALL_APT",
            "INSTALL_BUN"
        ]
    );
    assert_eq!(str_(args, &["INSTALL_CLAUDE"]), "true");
    assert_eq!(str_(args, &["INSTALL_NODE"]), "24");
    assert_eq!(str_(args, &["INSTALL_DOTNET"]), "10.0 8.0");
    assert_eq!(str_(args, &["INSTALL_JETBRAINS"]), "toolbox rider");
    assert_eq!(str_(args, &["INSTALL_APT"]), "");
    assert_eq!(str_(args, &["INSTALL_BUN"]), "false");
    assert_eq!(
        str_(&root, &["services", "desktop", "build", "context"]),
        "./.state/desktop"
    );
}

#[test]
fn an_empty_sandbox_toml_uses_the_defaults() {
    let f = Fixture::new();
    f.write_conf("");
    let root = generate_parsed(&f);
    let desktop = service(&root, "desktop");
    assert!(!has(&desktop, &["build", "args", "INSTALL_CLAUDE"]));
    assert_eq!(str_(&desktop, &["environment", "TITLE"]), "AI Sandbox");
    assert_eq!(str_(&desktop, &["environment", "SANDBOX_SUDO"]), "true");
    assert_eq!(str_(&desktop, &["mem_limit"]), "8g");
    assert!(!has(&desktop, &["cpus"]));
    assert!(!has(&desktop, &["devices"]));
    assert!(!has(&desktop, &["environment", "CUSTOM_USER"]));
    assert_eq!(
        binds(&root),
        [project(&f, false), sandbox_dir(&f), git_dir(&f)]
    );
}

// --- [desktop] and [env] ---------------------------------------------------------

#[test]
fn desktop_settings() {
    let f = Fixture::new();
    append(
        &f,
        "desktop",
        "sudo = false\nmemory = \"4g\"\ncpus = 2.5\ntimezone = \"Asia/Tokyo\"\ndevices = [\"/dev/dri:/dev/dri\"]\nsecurity_opt = [\"seccomp=unconfined\"]\nauth = { user = \"me\", password = \"secret\" }\n",
    );
    let d = service(&generate_parsed(&f), "desktop");
    assert_eq!(str_(&d, &["environment", "SANDBOX_SUDO"]), "false");
    assert_eq!(str_(&d, &["mem_limit"]), "4g");
    assert_eq!(str_(&d, &["cpus"]), "2.5");
    assert_eq!(str_(&d, &["environment", "TZ"]), "Asia/Tokyo");
    assert_eq!(seq(&d, &["devices"]), ["/dev/dri:/dev/dri"]);
    assert_eq!(seq(&d, &["security_opt"]), ["seccomp=unconfined"]);
    assert_eq!(str_(&d, &["environment", "CUSTOM_USER"]), "me");
    assert_eq!(str_(&d, &["environment", "PASSWORD"]), "secret");
}

#[test]
fn whole_cpus_are_written_as_numbers() {
    let f = Fixture::new();
    append(&f, "desktop", "cpus = 4\n");
    assert_eq!(
        str_(&service(&generate_parsed(&f), "desktop"), &["cpus"]),
        "4"
    );
    assert!(
        fs::read_to_string(f.generated_file())
            .unwrap()
            .contains("\n    cpus: 4\n")
    );
}

#[test]
fn env_vars_are_added_after_the_sandbox_ones() {
    let f = Fixture::new();
    f.write_conf(&(f.read_conf() + "\n[env]\nMY_VAR = \"a=b\"\nCOUNT = 3\nFLAG = true\n"));
    let env_keys = keys(at(
        &service(&generate_parsed(&f), "desktop"),
        &["environment"],
    ));
    let n = env_keys.len();
    assert_eq!(env_keys[n - 3..], ["MY_VAR", "COUNT", "FLAG"]);
    assert_eq!(env_keys[n - 4], "SANDBOX_WORKDIR");
    assert_eq!(env(&f, "MY_VAR"), "a=b");
    assert_eq!(env(&f, "COUNT"), "3");
    assert_eq!(env(&f, "FLAG"), "true");
}

/// Values go through `q`: quotes, backslashes, `: #`, newlines and Windows paths can't break or inject YAML.
#[test]
fn values_are_escaped() {
    let f = Fixture::new();
    let title = "My \"box\": #1 \\ yes\n  injected: true";
    f.write_conf(
        &(f.read_conf()
            .replace("title = \"AI Sandbox\"", &format!("title = '''{title}'''"))
            + "\n[env]\nWIN = 'C:\\Users\\me'\nTAB = \"a\\tb\\u0001\"\n"),
    );
    let d = service(&generate_parsed(&f), "desktop");
    assert_eq!(str_(&d, &["environment", "TITLE"]), title);
    assert_eq!(str_(&d, &["environment", "WIN"]), "C:\\Users\\me");
    assert_eq!(str_(&d, &["environment", "TAB"]), "a\tb\u{1}");
    assert!(!has(&d, &["injected"]));
    assert!(!has(&d, &["environment", "injected"]));
}

