#[test]
fn shares_are_mounted_after_the_project() {
    let f = Fixture::new();
    let docs = f.root.join("docs");
    let data = f.root.join("my data");
    fs::create_dir_all(&docs).unwrap();
    fs::create_dir_all(&data).unwrap();
    f.write_conf(&(f.read_conf() + "\n[[share]]\nhost = \"../docs\"\n\n[[share]]\nhost = \"../my data\"\npath = \"/data\"\nreadonly = false\n"));
    assert_eq!(
        binds(&generate_parsed(&f)),
        [
            project(&f, false),
            sandbox_dir(&f),
            git_dir(&f),
            bind(docs.as_str(), "/shares/docs", true),
            bind(data.as_str(), "/data", false)
        ]
    );
}

#[test]
fn shares_are_listed_by_info() {
    let f = Fixture::new();
    fs::create_dir_all(f.root.join("docs")).unwrap();
    f.write_conf(&(f.read_conf() + "\n[[share]]\nhost = \"../docs\"\n"));
    let r = f.run(&["info"]);
    assert_exit(&r, 0);
    assert_output(&r, "/shares/docs");
    assert_output(&r, "read-only");
}
